const COLORS = ['Off', 'Red', 'Green', 'Yellow', 'Blue', 'Magenta', 'Cyan', 'White'];
const pad2 = n => String(n).padStart(2, '0');
/* --verbose: every message to and from the desk is printed in the bridge window */
const LOG = { on: false, ring: [], seq: 0, add(dir, host, port, what) { this.ring.push({ n: ++this.seq, at: Date.now(), dir, host, port, what: String(what).slice(0, 200) }); if (this.ring.length > 400) this.ring.splice(0, this.ring.length - 400); }, note(what) { this.add('•', '', '', what); if (this.on) console.log('• ' + what); }, out(host, port, what) { this.add('→', host, port, what); if (this.on) console.log(`→ ${host}:${port}  ${what}`); }, in(host, port, what) { this.add('←', host, port, what); if (this.on) console.log(`← ${host}:${port}  ${what}`); } };
