/* ---------- models ---------- */
const aiNum = id => (String(id).match(/\d+(\.\d+)?/g) || []).map(Number);
const aiNewer = (a, b) => { const x = aiNum(a), y = aiNum(b); for (let i = 0; i < Math.max(x.length, y.length); i++) { if ((x[i] || 0) !== (y[i] || 0)) return (y[i] || 0) - (x[i] || 0); } return 0; };
