const monitorCheck = check;
const netScan = scan;
const nicList = cards;

const VERSION = '2.24.0';   // the bundle (tools/bundle-bridge.mjs) writes package.json's version here
const argv = process.argv.slice(2), opt = k => { const i = argv.indexOf(k); return i >= 0 ? argv[i + 1] : null; };
