const SETTINGS_FILE = path.join(CONFIG_DIR, 'bridge.json');
const SETTINGS = Object.assign({ readOnly: false, allow48: true, allowScenes: false, allowRf: false, allowGain: false, allowPatch: false, allowStrip: false }, (() => { try { return JSON.parse(fs.readFileSync(SETTINGS_FILE, 'utf8')); } catch (e) { return {}; } })());
const SHARE_PORT = +(opt('--share-port') || process.env.LAPIS_SHARE_PORT || 52410);
