const DUMP = { running: false, progress: null, result: null, error: null };
/* one short-lived copy of this program as the AI tools (--mcp): send it JSON-RPC lines, get the answers back */
function toolProc(dir, msgs) {
  return new Promise((ok, bad) => {
    let sea = false; try { sea = process.getBuiltinModule('node:sea').isSea(); } catch (e) { }
    const p = spawn(process.execPath, (sea ? [] : [process.argv[1]]).concat(['--mcp', '--root', dir]), { stdio: ['pipe', 'pipe', 'pipe'], windowsHide: true });
    let out = '', err = ''; const t = setTimeout(() => { p.kill(); bad(new Error('The tool took longer than three minutes.')); }, 180000);
    p.stdout.on('data', d => { out += d; }); p.stderr.on('data', d => { err += d; }); p.on('error', e => { clearTimeout(t); bad(e); });
    p.on('close', () => { clearTimeout(t); const r = out.split('\n').filter(Boolean).map(l => { try { return JSON.parse(l); } catch (e) { return null; } }).filter(Boolean); if (!r.length) return bad(new Error('The AI tools did not start' + (err ? ': ' + err.slice(0, 300) : '.'))); ok(r); });
    p.stdin.end(msgs.map(m => JSON.stringify(m)).join('\n') + '\n');
  });
}
let TOOL_LIST = null;
async function toolList() { if (!TOOL_LIST) TOOL_LIST = (await toolProc(os.tmpdir(), [{ jsonrpc: '2.0', id: 1, method: 'tools/list' }]))[0].result.tools; return TOOL_LIST; }
function openApi(tools) {
  const paths = {}; tools.forEach(t => { paths['/v2/tools/' + t.name] = { post: { operationId: t.name, summary: t.description.split('. ')[0].slice(0, 120), description: t.description, requestBody: { required: true, content: { 'application/json': { schema: t.inputSchema } } },
    responses: { 200: { description: 'The result as JSON.', content: { 'application/json': { schema: { type: 'object' } } } }, 422: { description: 'Refused: "errors" lists the path, the problem and a valid value.', content: { 'application/json': { schema: { type: 'object' } } } }, 401: { description: 'Wrong or missing pairing code.' } } } }; });
  return { openapi: '3.1.0', info: { title: 'Lapis design-time tools', version: VERSION, description: 'Build and check live-sound show files (.lapis.json) in the shows folder of this computer: console and racks, input and output lists, wireless plan, PA design, printable documents. The same tools as the Lapis MCP server. Changes are previews unless "apply" is true; applied values wait for a person\'s review in Lapis. Nothing here operates hardware. Start with lapis_guide.' },
    servers: [{ url: 'http://127.0.0.1:' + PORT }], security: [{ pairingCode: [] }], components: { securitySchemes: { pairingCode: { type: 'apiKey', in: 'header', name: 'X-Lapis-Key', description: 'The six-digit pairing code the Lapis Bridge window shows (or the value of --key).' } } }, paths };
}
